        sse_encode_i_32(0, serializer);
        sse_encode_playback_state_dto(state, serializer);
        sse_encode_opt_box_autoadd_i_64(trackId, serializer);
        sse_encode_u_64(positionMs, serializer);
        sse_encode_u_64(durationMs, serializer);
      case CoreEventDto_PositionTick(
        positionMs: final positionMs,
        bufferedMs: final bufferedMs,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_u_64(positionMs, serializer);
        sse_encode_u_64(bufferedMs, serializer);
      case CoreEventDto_QueueChanged(
        length: final length,
        currentIndex: final currentIndex,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_u_32(length, serializer);
        sse_encode_opt_box_autoadd_u_32(currentIndex, serializer);
      case CoreEventDto_ScanProgress(
        sourceId: final sourceId,
        phase: final phase,
        done: final done,
        total: final total,
      ):
        sse_encode_i_32(3, serializer);
        sse_encode_i_64(sourceId, serializer);
        sse_encode_scan_phase_dto(phase, serializer);
        sse_encode_u_64(done, serializer);
        sse_encode_opt_box_autoadd_u_64(total, serializer);
      case CoreEventDto_ScanFinished(
        sourceId: final sourceId,
        added: final added,
        updated: final updated,
        removed: final removed,
      ):
        sse_encode_i_32(4, serializer);
        sse_encode_i_64(sourceId, serializer);
        sse_encode_u_64(added, serializer);
        sse_encode_u_64(updated, serializer);
        sse_encode_u_64(removed, serializer);
      case CoreEventDto_LibraryChanged(scope: final scope):
        sse_encode_i_32(5, serializer);
        sse_encode_library_scope_dto(scope, serializer);
      case CoreEventDto_EnrichQueueChanged(pending: final pending):
        sse_encode_i_32(6, serializer);
